#!/usr/bin/env bash
# Generated by Suite Builder. EDIT RULES: do not edit this file; regenerating replaces all of it. Your Jira names go in jira-loop/jira.properties; when it runs, in the pipeline files.
# The crew's job, the same in every pipeline: the stories the claim job took, each worked on by the AI crew
# (Claude Code, /stories) from the same commit, the suite's checks run on its tests, and each committed as a
# branch, bundled in jira-loop/run/ for the publish job (node jira-loop/agents.mjs crew). Given ANTHROPIC_API_KEY
# and nothing else: a story's text comes from Jira, so the crew is never in a job that holds the tracker's token
# or one that can write to the repository. It stops, changing nothing, when it is given one.
set -euo pipefail
cd "$(dirname "$0")/.."

if [ -z "${ANTHROPIC_API_KEY:-}" ]; then
  echo "ANTHROPIC_API_KEY is not set: add it to the pipeline's secrets (never to a file in the suite)."
  exit 1
fi
for name in JIRA_API_TOKEN JIRA_EMAIL SUITE_GIT_TOKEN SUITE_GIT_BEARER SUITE_PUSH_TOKEN GH_TOKEN GITHUB_TOKEN SYSTEM_ACCESSTOKEN AZURE_DEVOPS_EXT_PAT; do
  if [ -n "${!name:-}" ]; then
    echo "The crew's job was given $name: give it to the claim and publish jobs only (the pipeline file, or the secret's scope)."
    exit 1
  fi
done
if git config --get-regexp '^http\..*extraheader$' > /dev/null; then
  echo "The checkout left a git credential in .git/config: check out without it (persist-credentials: false)."
  exit 1
fi

# The dependencies, once, so the crew's checks run offline.
mvn -B -q test -Dtest=SuiteRulesTest
SUITE_CREW='npx --yes @anthropic-ai/claude-code@2.1.296 -p "/stories {key}" --permission-mode acceptEdits --allowedTools "Read,Glob,Grep,Edit,Write,Bash(mvn -o:*),Bash(node jira-loop/agents.mjs need:*)"'
# The crew was told to run these; each story's are run again, so nothing it reports is unchecked.
SUITE_CHECKS='mvn -B -q -o test-compile
mvn -B -o test -Dtest=SuiteRulesTest'
export SUITE_CREW SUITE_CHECKS
node jira-loop/agents.mjs crew
